SELECT * FROM ( SELECT r.REVIEW_ID, r.ACCOUNT_ID, a.ACCOUNT_NAME, r.PLACE_ID, r.PLACE_TYPE, r.CONTENT, r.CREATED_AT, r.UPDATED_AT, ROW_NUMBER() OVER ( ORDER BY
r.REVIEW_ID ASC r.REVIEW_ID DESC r.CREATED_AT ASC r.CREATED_AT DESC
) AS RN FROM REVIEWS r INNER JOIN ACCOUNT_TBL a ON r.ACCOUNT_ID = a.ACCOUNT_ID
AND r.PLACE_ID = #{params.placeId}
AND r.ACCOUNT_ID = #{params.accountId}
AND r.PLACE_TYPE = #{params.placeType}
) WHERE RN BETWEEN (#{params.page} * #{params.size} + 1) AND ((#{params.page} + 1) * #{params.size})

SELECT COUNT(*)
FROM REVIEWS r


        AND r.PLACE_ID = #{params.placeId}


        AND r.ACCOUNT_ID = #{params.accountId}


        AND r.PLACE_TYPE = #{params.placeType}

SELECT COUNT(*)
FROM REVIEWS
WHERE PLACE_ID = #{placeId}

SELECT ACCOUNT_ID
FROM REVIEWS
WHERE REVIEW_ID = #{reviewId}
